def userId = execution.getVariable('initiator')
def identity = org.flowable.engine.impl.util.CommandContextUtil.getIdmIdentityService()
def user = userId == null ? null : identity.createUserQuery().userId(userId).singleResult()
def fullName = user == null ? userId : ((user.firstName ?: '') + ' ' + (user.lastName ?: '')).trim()
if (!fullName) {
  fullName = userId
}
execution.setVariable('employeeName', fullName)

def identity = org.flowable.engine.impl.util.CommandContextUtil.getIdmIdentityService()
def displayName = { userId ->
  if (!userId) return ''
  def user = identity.createUserQuery().userId(userId).singleResult()
  if (user == null) return userId.toString()
  def n = ((user.firstName ?: '') + ' ' + (user.lastName ?: '')).trim()
  return n ?: userId.toString()
}
def empId = (execution.getVariable('employeeId') ?: 'NA').toString()
def empName = (execution.getVariable('employeeName') ?: '').toString()
def reason = (execution.getVariable('resignationReason') ?: '').toString()
def lwd = execution.getVariable('lastWorkingDay')
def lwdDate = lwd instanceof Date ? lwd : null
if (lwdDate == null && lwd != null && lwd.toString().length() >= 10) {
  try {
    lwdDate = new java.text.SimpleDateFormat('yyyy-MM-dd').parse(lwd.toString().substring(0, 10))
  } catch (Exception e) {
    lwdDate = null
  }
}
def lwdText = lwdDate == null ? (lwd == null ? '' : lwd.toString()) : new java.text.SimpleDateFormat('dd/MM/yyyy').format(lwdDate)
def lwdKey = lwdDate == null ? '' : new java.text.SimpleDateFormat('ddMMyyyy').format(lwdDate)
def caseNumber = execution.getVariable('caseNumber')
if (caseNumber == null || caseNumber.toString().trim() == '') {
  def datePart = lwdKey ? lwdKey : new java.text.SimpleDateFormat('ddMMyyyy').format(new Date())
  caseNumber = 'RES-' + empId + '-' + datePart
  execution.setVariable('caseNumber', caseNumber)
  def runtime = org.flowable.engine.impl.util.CommandContextUtil.getProcessEngineConfiguration().getRuntimeService()
  runtime.updateBusinessKey(execution.getProcessInstanceId(), caseNumber.toString())
  runtime.setProcessInstanceName(execution.getProcessInstanceId(), 'Resignation - ' + empName + ' (' + caseNumber + ')')
}
def decisionVar = ''
def remarksVar = ''
def remarksRaw = remarksVar ? execution.getVariable(remarksVar) : null
def remarksText = remarksRaw == null ? '' : remarksRaw.toString().trim()
def raw = decisionVar ? execution.getVariable(decisionVar) : null
def decision
if (decisionVar) {
  def approved = raw == true || raw == 'true' || raw == 'Yes' || raw == 'Approve'
  def rejected = raw == false || raw == 'false' || raw == 'No' || raw == 'Reject'
  decision = approved ? 'Approved' : (rejected ? 'Rejected' : 'Completed')
} else if ('Employee (MPE)' == 'Employee (MPE)') {
  decision = 'Submitted'
} else {
  decision = 'Completed'
}
def inbox
def teamLead
if (decision == 'Rejected') {
  teamLead = empName
  inbox = 'Resignation closed - no further task'
} else {
  inbox = 'ASE: Resignation - ' + empName + ' (' + empId + ')'
  teamLead = 'rest-admin' ? displayName('rest-admin') : ('' ? '' : 'Team')
}
def intro
if (decision == 'Approved') {
  intro = '<p><b>Employee (MPE)</b> has <b>Approved</b> the resignation request from <b>' + empName + '</b>.</p>'
} else if (decision == 'Rejected') {
  intro = '<p><b>Employee (MPE)</b> has <b>Rejected</b> the resignation request from <b>' + empName + '</b>.</p>'
} else if (decision == 'Submitted') {
  intro = '<p>A request for <b>Resignation</b> is sent to you by <b>' + empName + '</b>.</p>'
} else {
  intro = '<p><b>Employee (MPE)</b> has completed this step for <b>' + empName + '</b>.</p>'
}
