html = html.replace('__TEAM_LEAD__', teamLead.toString())
html = html.replace('__INTRO__', intro)
html = html.replace('__CASE__', caseNumber.toString())
html = html.replace('__DECISION__', decision)
html = html.replace('__INBOX__', inbox.toString())
